/* 把 8 位二进制位模式 u 的低 8 位写成一个以 '\0' 结尾的字符串（out 至少 9 字节）。 */
static void to_bits8(unsigned int u, char *out)
{
    int i;

    for (i = 7; i >= 0; i--) {
        out[7 - i] = (char)('0' + (int)((u >> i) & 1u));
    }
    out[8] = '\0';
}

