/* 用位运算判断 8 位有符号数 a + b 是否溢出。a、b 取值范围 -128 ~ 127，按补码理解。
   把截断成 8 位后的和写入 *sum（仍按 -128 ~ 127 解释，即把最高位看作符号位）。
   溢出返回 1，不溢出返回 0。 */
int add_overflow(int a, int b, int *sum)
{
    /* TODO:
       1) 把 a、b 都按低 8 位转成无符号数 ua、ub（负数转无符号是良定义的，直接取 & 0xFF）；
       2) 相加后只保留低 8 位得到结果的无符号形式 ur；
       3) 溢出条件（位运算）：两个加数符号相同、而结果符号与它们不同，
          即 ((ua ^ ur) & (ub ^ ur)) 的最高位为 1；
       4) ur 最高位为 1 表示结果是负数，把它减去 256 才是 -128 ~ 127 的十进制值。 */
    (void)a;
    (void)b;
    *sum = 0;
    return 0;
}

static void show_add(int a, int b)
{
    int sum = 0;
    int ov = add_overflow(a, b, &sum);

    printf("true=%d truncated=%d overflow=%s\n", a + b, sum, ov ? "YES" : "NO");
}

static void show_sub(int a, int b)
{
    int sum = 0;
    int ov = add_overflow(a, -b, &sum);   /* a - b 等价于 a + (-b) */

    printf("true=%d truncated=%d overflow=%s\n", a - b, sum, ov ? "YES" : "NO");
}

int main(void)
{
    show_add(100, 50);
    show_add(100, -50);
    show_sub(-100, 50);
    show_sub(-100, -50);

    return 0;
}

