/* 计算直接映射 Cache 的地址划分。
   addr_bits : 主存地址位数
   block_size: 块大小（字节），必须是 2 的幂
   line_count: Cache 的行数，必须是 2 的幂
   通过指针返回标记位数 *tag_bits、行号位数 *line_bits、块内偏移位数 *offset_bits，
   且满足 tag_bits + line_bits + offset_bits == addr_bits。 */
void cache_field_bits(int addr_bits, int block_size, int line_count,
                      int *tag_bits, int *line_bits, int *offset_bits)
{
    /* TODO: 块内偏移位数 = log2(block_size)；行号位数 = log2(line_count)；
       标记位数 = addr_bits - 行号位数 - 块内偏移位数。
       求以 2 为底的对数可以用 while (x > 1) { x >>= 1; n++; } 实现。 */
    (void)addr_bits;
    (void)block_size;
    (void)line_count;
    *tag_bits = 0;
    *line_bits = 0;
    *offset_bits = 0;
}

/* 按直接映射把地址 addr 拆成标记、行号和块内偏移。
   line_bits、offset_bits 由 cache_field_bits 给出。 */
void split_address(unsigned int addr, int line_bits, int offset_bits,
                   unsigned int *tag, unsigned int *line, unsigned int *offset)
{
    /* TODO: 先造出 offset_bits 位和 line_bits 位的掩码；
       块内偏移 = addr 的低 offset_bits 位；
       行号 = addr 右移 offset_bits 位后再取低 line_bits 位；
       标记 = addr 右移 (offset_bits + line_bits) 位。 */
    (void)addr;
    (void)line_bits;
    (void)offset_bits;
    *tag = 0u;
    *line = 0u;
    *offset = 0u;
}

int main(void)
{
    int addr_bits = 32;
    int block_size = 64;
    int line_count = 128;          /* Cache 数据区 = 128 行 * 64 B = 8 KB */
    int tag_bits, line_bits, offset_bits;
    unsigned int addr = 0x12345678u;
    unsigned int tag, line, offset;

    cache_field_bits(addr_bits, block_size, line_count, &tag_bits, &line_bits, &offset_bits);
    printf("%d %d %d\n", tag_bits, line_bits, offset_bits);

    split_address(addr, line_bits, offset_bits, &tag, &line, &offset);
    printf("0x%08X: offset=%u line=%u tag=0x%X\n", addr, offset, line, tag);

    return 0;
}

#include <stdio.h>

/* 计算 4 路组相联 Cache 的地址划分。
   addr_bits : 主存地址位数
   block_size: 块大小（字节），必须是 2 的幂
   set_count : 组数，必须是 2 的幂
   通过指针返回标记位数 *tag_bits、组号位数 *set_bits、块内偏移位数 *offset_bits，
   且满足 tag_bits + set_bits + offset_bits == addr_bits。 */
void set_assoc_field_bits(int addr_bits, int block_size, int set_count,
                          int *tag_bits, int *set_bits, int *offset_bits)
{
    /* TODO: 块内偏移位数 = log2(block_size)；组号位数 = log2(set_count)；
       标记位数 = addr_bits - 组号位数 - 块内偏移位数。 */
    (void)addr_bits;
    (void)block_size;
    (void)set_count;
    *tag_bits = 0;
    *set_bits = 0;
    *offset_bits = 0;
}

/* 求地址 addr 所属的组号。 */
unsigned int set_index(unsigned int addr, int offset_bits, int set_bits)
{
    /* TODO: 组号 = (addr >> offset_bits) 的低 set_bits 位。 */
    (void)addr;
    (void)offset_bits;
    (void)set_bits;
    return 0u;
}

/* 求地址 addr 的标记。 */
unsigned int tag_of(unsigned int addr, int offset_bits, int set_bits)
{
    /* TODO: 标记 = addr >> (offset_bits + set_bits)。 */
    (void)addr;
    (void)offset_bits;
    (void)set_bits;
    return 0u;
}

int main(void)
{
    int addr_bits = 32;
    int block_size = 32;
    int ways = 4;
    int set_count = 128;           /* 16 KB / 32 B / 4 路 = 128 组 */
    int tag_bits, set_bits, offset_bits;
    unsigned int addr = 0x12345678u;
    unsigned int s, tag, offset;
    int i;

    set_assoc_field_bits(addr_bits, block_size, set_count, &tag_bits, &set_bits, &offset_bits);
    printf("%d %d %d\n", tag_bits, set_bits, offset_bits);

    s = set_index(addr, offset_bits, set_bits);
    tag = tag_of(addr, offset_bits, set_bits);
    offset = addr & ((1u << offset_bits) - 1u);
    printf("0x%08X: offset=%u set=%u tag=0x%X\n", addr, offset, s, tag);

    printf("lines=");
    for (i = 0; i < ways; i++) {
        printf("%s%u", (i == 0) ? "" : " ", s * (unsigned int)ways + (unsigned int)i);
    }
    printf("\n");

    return 0;
}

