/* 解析 32 位 IEEE 754 单精度浮点数的位模式 bits。
   *sign     : 符号位原样返回，0 表示正、1 表示负
   *exponent : 8 位阶码，按无符号数返回（0 ~ 255）
   *fraction : 23 位尾数（隐含的整数位 1 不包含在内）
   *value    : 该位模式对应的单精度浮点数的值 */
void decode_float(unsigned int bits, int *sign, int *exponent,
                  unsigned int *fraction, float *value)
{
    /* TODO:
       符号位 = bits 的第 31 位；
       阶码   = bits 的第 30 ~ 23 位；
       尾数   = bits 的低 23 位；
       数值   = 用 union { unsigned int u; float f; } 把同一个位模式直接解释成 float。 */
    (void)bits;
    *sign = 0;
    *exponent = 0;
    *fraction = 0u;
    *value = 0.0f;
}

int main(void)
{
    unsigned int patterns[3] = { 0xC1480000u, 0x3FC00000u, 0x40490FDBu };
    int i;

    for (i = 0; i < 3; i++) {
        int sign, exponent;
        unsigned int fraction;
        float value;

        decode_float(patterns[i], &sign, &exponent, &fraction, &value);
        printf("0x%08X: sign=%d exponent=%d unbiased=%d fraction=0x%06X value=%g\n",
               patterns[i], sign ? -1 : 1, exponent, exponent - 127, fraction, (double)value);
    }

    return 0;
}

