/* 用模 2 长除法（逐位异或，不产生进位和借位）求 CRC 余数。
   data : 数据位串，长度为 len，只含 '0' 和 '1'
   gen  : 生成多项式位串，长度为 glen，最高位必须是 '1'
   out  : 余数位串，长度为 glen - 1，以 '\0' 结尾（out 至少 glen 个字节）

   做法：在 data 后面补 glen - 1 个 '0' 得到被除数（共 len + glen - 1 位）；
   从左到右扫描，当前位是 '1' 时，把从它开始的 glen 位与生成多项式逐位异或；
   扫描结束后，末尾的 glen - 1 位就是余数。 */
void crc_remainder(const char *data, int len, const char *gen, int glen, char *out)
{
    /* TODO: 用一个临时字符数组保存被除数，按上面的规则逐位异或，
       最后把末尾的 glen - 1 位拷贝到 out，并补上 '\0'。 */
    int i;

    (void)data;
    (void)len;
    (void)gen;
    for (i = 0; i < glen - 1; i++) {
        out[i] = '0';
    }
    out[glen - 1] = '\0';
}

int main(void)
{
    const char *data = "1011001";
    const char *gen = "10011";        /* G(x) = x^4 + x + 1 */
    char rem[16];
    int len = (int)strlen(data);
    int glen = (int)strlen(gen);

    crc_remainder(data, len, gen, glen, rem);
    printf("remainder=%s\n", rem);
    printf("codeword=%s%s\n", data, rem);

    return 0;
}
